import torch
for x in (torch.tensor([[5., 1.], [5., 1.001]]), torch.tensor([[7., -3.]]), torch.tensor([[2.], [4.]])):
    gamma = torch.full((x.shape[-1],), 2.); beta = torch.full_like(gamma, -1.)
    y = batch_norm(x, gamma, beta, eps=0.25)
    if x.shape[0] == 1:
        expected = beta.unsqueeze(0)
    else:
        expected = torch.nn.functional.batch_norm(x, None, None, gamma, beta, training=True, eps=0.25)
    assert torch.isfinite(y).all() and torch.allclose(y, expected, atol=1e-6)
print('ok')
